import{_ as e,a as o,b as s,c as r,d as a}from"./chunks/26-dashboard-player.BKek0GVz.js";import{_ as d,o as n,c as i,a2 as c}from"./chunks/framework.BM5YPQmL.js";const y=JSON.parse('{"title":"The dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),h={name:"guide/dashboard.md"};function p(l,t,g,m,u,f){return n(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="the-dashboard" tabindex="-1">The dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The dashboard&quot;">​</a></h1><p><code>reelforge studio</code> (or <code>start.bat</code> / <code>start.sh</code>) opens the dashboard at <code>http://127.0.0.1:4310</code>. It lists <strong>your episodes</strong> (the <code>episodes/</code> folder) and the <strong>examples</strong>.</p><p><img src="'+e+'" alt="Dashboard"></p><p>Each card shows a live thumbnail, the series, preset, number of lines and scenes, the duration, and status chips:</p><table tabindex="0"><thead><tr><th>Chip</th><th>Meaning</th></tr></thead><tbody><tr><td><code>voice 1:15</code> / <code>no voice</code></td><td>Whether a recording is present, and its length</td></tr><tr><td><code>cues 24/24</code> / <code>draft cues</code> / <code>no cues</code></td><td>How many sentences are marked; draft cues are estimates</td></tr><tr><td><code>valid</code> / <code>2 warnings</code> / <code>1 error</code></td><td>Result of the static checks (hover an error to read it)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Upload voice</strong></td><td>Choose a recording; it is converted to <code>voice.wav</code> (48 kHz)</td></tr><tr><td><strong>Open editor</strong></td><td>Opens the visual editor for this episode in a new tab (see <a href="./editor.html">The editor</a>)</td></tr><tr><td><strong>Mark cues</strong></td><td>Opens the editor in Cues mode, ready to mark when each sentence starts</td></tr><tr><td><strong>Auto cues</strong></td><td>Aligns every line and word to the recording (see <a href="./timing.html">Timing, cues and alignment</a>)</td></tr><tr><td><strong>Validate</strong></td><td>Runs every check, including the headless text-overflow and caption checks</td></tr><tr><td><strong>Render</strong></td><td>Choose the platform preset, share size, SFX and speed; progress, FPS and ETA appear live; <strong>Cancel</strong> stops cleanly</td></tr><tr><td><strong>Folder</strong></td><td>Opens the episode folder in your file manager</td></tr><tr><td><strong>Draft cues</strong></td><td>(only without cues) estimates timing from the text</td></tr></tbody></table><p>To start from an industry template, click <strong>+ New episode</strong> and choose <strong>Start from template</strong>: pick a pack and a template, fill in the fields and the language, and the episode opens in the editor (see <a href="./templates-and-packs.html">Templates and packs</a>).</p><p><img src="'+o+'" alt="Validation results"></p><p><img src="'+s+'" alt="Render options"></p><p><img src="'+r+'" alt="Live render progress"></p><p>Finished outputs appear as links on the card: videos open in a player with a <strong>Download</strong> button.</p><p><img src="'+a+'" alt="Built-in player"></p><p>The <strong>Gallery</strong> page (<code>/gallery</code>) shows what you can build with. <strong>Components</strong> lists all 62 components by category with a search box and a preview frame from the component gallery; click one for its props and a YAML snippet to copy. <strong>Themes</strong> previews every built-in and project theme from its colors and fonts, with its light or dark mode and a WCAG contrast check. <strong>Packs</strong> lists the industry packs in English or Arabic; <strong>Use this template</strong> opens the new-episode dialog with that template selected.</p><p>The <strong>Connect AI</strong> page (<code>/connect</code>) has copy-paste setup for AI clients; see <a href="./ai.html">AI integration</a>.</p><p>The <strong>Documentation</strong> button opens this documentation at <code>/docs/</code>, served from your ReelForge folder, so it works offline. It has the same pages as the online site, in English and Arabic (switch with the language menu), with search.</p><p>Only one render runs at a time. The dashboard listens on <code>127.0.0.1</code> by default, so other computers cannot reach it. <code>--host</code> binds it elsewhere and then requires a bearer token for the AI endpoints (see <a href="./ai.html#security">security</a>).</p>',16)])])}const w=d(h,[["render",p]]);export{y as __pageData,w as default};
